    correction: [{"quoi":"العامل المشترك","math":"العامل المشترك هو <span dir=\"ltr\" class=\"expr\">3<sup>-13</sup></span>، و هو موجود في كلّ الحدود"},{"quoi":"نُخرج العامل المشترك","math":"<span dir=\"ltr\" class=\"expr\">A = 3<sup>-13</sup> × (2<sup>5</sup> - 5)</span>"},{"quoi":"ننجز القوس","math":"<span dir=\"ltr\" class=\"expr\">2<sup>5</sup> - 5 = 27</span>"},{"quoi":"نعيد الكتابة","math":"<span dir=\"ltr\" class=\"expr\">A = 3<sup>-13</sup> × 27</span>"},{"quoi":"نلاحظ","math":"العدد 27 هو <span dir=\"ltr\" class=\"expr\">(<span class=\"frac\"><span class=\"num\">1</span><span class=\"den\">3</span></span>)<sup>-3</sup></span>"},{"quoi":"و العامل المشترك","math":"<span dir=\"ltr\" class=\"expr\">3<sup>-13</sup> = (<span class=\"frac\"><span class=\"num\">1</span><span class=\"den\">3</span></span>)<sup>13</sup></span>"},{"quoi":"القاعدة","math":"<span dir=\"ltr\" class=\"expr\">a^n × a^p = a^(n+p)</span>"},{"quoi":"نجمع الأسّين","math":"<span dir=\"ltr\" class=\"expr\">13 + (-3) = 10</span>"},{"quoi":"النتيجة","math":"<span dir=\"ltr\" class=\"expr\">A = (<span class=\"frac\"><span class=\"num\">1</span><span class=\"den\">3</span></span>)<sup>10</sup></span>"}],
