    correction: [{"quoi":"نحدّد الأولوية","math":"الأقواس أوّلا، ثمّ القوى، ثمّ الضرب و القسمة، ثمّ الجمع و الطرح"},{"quoi":"ننجز داخل القوس","math":"<span dir=\"ltr\" class=\"expr\">2 + (3<sup>2</sup>)<sup>2</sup> - (4 - 3)<sup>3</sup> + 35<sup>17</sup> × 0<sup>33</sup> = 2 + (9)<sup>2</sup> - (4 - 3)<sup>3</sup> + 35<sup>17</sup> × 0<sup>33</sup></span>"},{"quoi":"ننجز داخل القوس","math":"<span dir=\"ltr\" class=\"expr\">2 + (9)<sup>2</sup> - (4 - 3)<sup>3</sup> + 35<sup>17</sup> × 0<sup>33</sup> = 2 + 9<sup>2</sup> - (4 - 3)<sup>3</sup> + 35<sup>17</sup> × 0<sup>33</sup></span>"},{"quoi":"ننجز داخل القوس","math":"<span dir=\"ltr\" class=\"expr\">2 + 9<sup>2</sup> - (4 - 3)<sup>3</sup> + 35<sup>17</sup> × 0<sup>33</sup> = 2 + 9<sup>2</sup> - (1)<sup>3</sup> + 35<sup>17</sup> × 0<sup>33</sup></span>"},{"quoi":"نزيل الأقواس","math":"<span dir=\"ltr\" class=\"expr\">2 + 9<sup>2</sup> - (1)<sup>3</sup> + 35<sup>17</sup> × 0<sup>33</sup> = 2 + 9<sup>2</sup> - 1<sup>3</sup> + 35<sup>17</sup> × 0<sup>33</sup></span>"},{"quoi":"ننجز القوى","math":"<span dir=\"ltr\" class=\"expr\">2 + 9<sup>2</sup> - 1<sup>3</sup> + 35<sup>17</sup> × 0<sup>33</sup> = 2 + 81 - 1 + 177482997121587371826171875 × 0</span>"},{"quoi":"ننجز الضرب","math":"<span dir=\"ltr\" class=\"expr\">2 + 81 - 1 + 177482997121587371826171875 × 0 = 2 + 81 - 1 + 0</span>"},{"quoi":"ننجز آخر عملية","math":"<span dir=\"ltr\" class=\"expr\">2 + 81 - 1 + 0 = 82</span>"},{"quoi":"النتيجة","math":"<span dir=\"ltr\" class=\"expr\">A = 82</span>"}],
