    correction: [{"quoi":"نحدّد الأولوية","math":"الأقواس أوّلا، ثمّ القوى، ثمّ الضرب و القسمة، ثمّ الجمع و الطرح"},{"quoi":"ننجز داخل القوس","math":"<span dir=\"ltr\" class=\"expr\">5<sup>3</sup> - (3<sup>2</sup> - 2<sup>3</sup>) × 4<sup>2</sup> + 45<sup>0</sup> = 5<sup>3</sup> - (9 - 8) × 4<sup>2</sup> + 45<sup>0</sup></span>"},{"quoi":"ننجز داخل القوس","math":"<span dir=\"ltr\" class=\"expr\">5<sup>3</sup> - (9 - 8) × 4<sup>2</sup> + 45<sup>0</sup> = 5<sup>3</sup> - (1) × 4<sup>2</sup> + 45<sup>0</sup></span>"},{"quoi":"نزيل الأقواس","math":"<span dir=\"ltr\" class=\"expr\">5<sup>3</sup> - (1) × 4<sup>2</sup> + 45<sup>0</sup> = 5<sup>3</sup> - 1 × 4<sup>2</sup> + 45<sup>0</sup></span>"},{"quoi":"ننجز القوى","math":"<span dir=\"ltr\" class=\"expr\">5<sup>3</sup> - 1 × 4<sup>2</sup> + 45<sup>0</sup> = 125 - 1 × 16 + 1</span>"},{"quoi":"ننجز الضرب","math":"<span dir=\"ltr\" class=\"expr\">125 - 1 × 16 + 1 = 125 - 16 + 1</span>"},{"quoi":"ننجز آخر عملية","math":"<span dir=\"ltr\" class=\"expr\">125 - 16 + 1 = 110</span>"},{"quoi":"النتيجة","math":"<span dir=\"ltr\" class=\"expr\">A = 110</span>"}],
