    correction: [{"quoi":"المتطابقة","math":"<span dir=\"ltr\" class=\"expr\">(a - b)(a + b) = a<sup>2</sup> - b<sup>2</sup></span>"},{"quoi":"نحدّد a و b","math":"<span dir=\"ltr\" class=\"expr\">a = 2</span>، و <span dir=\"ltr\" class=\"expr\">b = √3</span>"},{"quoi":"نطبّق المتطابقة","math":"<span dir=\"ltr\" class=\"expr\">(2 - √3) × (2 + √3) = (2)<sup>2</sup> - (√3)<sup>2</sup></span>"},{"quoi":"نحسب المربّعين","math":"<span dir=\"ltr\" class=\"expr\">(2)<sup>2</sup> = 4</span>، و <span dir=\"ltr\" class=\"expr\">(√3)<sup>2</sup> = 3</span>"},{"quoi":"النتيجة","math":"<span dir=\"ltr\" class=\"expr\">A = 1</span>"}],
