    correction: [{"quoi":"المتطابقة","math":"<span dir=\"ltr\" class=\"expr\">(a - b)(a + b) = a<sup>2</sup> - b<sup>2</sup></span>"},{"quoi":"نحدّد a و b","math":"<span dir=\"ltr\" class=\"expr\">a = 5√2</span>، و <span dir=\"ltr\" class=\"expr\">b = 7</span>"},{"quoi":"نطبّق المتطابقة","math":"<span dir=\"ltr\" class=\"expr\">(5√2 - 7) × (5√2 + 7) = (5√2)<sup>2</sup> - (7)<sup>2</sup></span>"},{"quoi":"نحسب المربّعين","math":"<span dir=\"ltr\" class=\"expr\">(5√2)<sup>2</sup> = 50</span>، و <span dir=\"ltr\" class=\"expr\">(7)<sup>2</sup> = 49</span>"},{"quoi":"النتيجة","math":"<span dir=\"ltr\" class=\"expr\">A = 1</span>"}],
