    correction: [{"quoi":"المتطابقة","math":"<span dir=\"ltr\" class=\"expr\">(a - b)(a + b) = a<sup>2</sup> - b<sup>2</sup></span>"},{"quoi":"نحدّد a و b","math":"<span dir=\"ltr\" class=\"expr\">a = 5</span>، و <span dir=\"ltr\" class=\"expr\">b = 2√6</span>"},{"quoi":"نطبّق المتطابقة","math":"<span dir=\"ltr\" class=\"expr\">(5 - 2√6) × (5 + 2√6) = (5)<sup>2</sup> - (2√6)<sup>2</sup></span>"},{"quoi":"نحسب المربّعين","math":"<span dir=\"ltr\" class=\"expr\">(5)<sup>2</sup> = 25</span>، و <span dir=\"ltr\" class=\"expr\">(2√6)<sup>2</sup> = 24</span>"},{"quoi":"النتيجة","math":"<span dir=\"ltr\" class=\"expr\">A = 1</span>"}],
