    enonce: "نعتبر <span dir=\"ltr\" class=\"expr\">A = √3</span> و <span dir=\"ltr\" class=\"expr\">B = -√2</span>، و قد رأينا أنّ <span dir=\"ltr\" class=\"expr\">(A - B)(A + B) = 1</span> أحسب<span dir=\"ltr\" class=\"expr\">: (A - B)<sup>14</sup> (A + B)<sup>15</sup> = (√3 + √2)<sup>14</sup> × (√3 - √2)<sup>15</sup></span>",
    correction: [{"quoi":"العددان مترافقان","math":"<span dir=\"ltr\" class=\"expr\">(a - b)(a + b) = a<sup>2</sup> - b<sup>2</sup></span>"},{"quoi":"نحسب جداء الأساسين","math":"<span dir=\"ltr\" class=\"expr\">(√3 + √2) × (√3 - √2) = 1</span>"},{"quoi":"نفصل ما يتقابل","math":"<span dir=\"ltr\" class=\"expr\">(√3 + √2)<sup>14</sup> × (√3 - √2)<sup>15</sup> = ((√3 + √2) × (√3 - √2))<sup>14</sup> × (√3 - √2)</span>"},{"quoi":"نعوّض بالجداء","math":"<span dir=\"ltr\" class=\"expr\">((√3 + √2) × (√3 - √2))<sup>14</sup> = 1<sup>14</sup></span>"},{"quoi":"قوّة العدد 1","math":"<span dir=\"ltr\" class=\"expr\">1<sup>14</sup> = 1</span>"},{"quoi":"النتيجة","math":"<span dir=\"ltr\" class=\"expr\">A = √3 - √2</span>"}],
