    enonce: "نعتبر <span dir=\"ltr\" class=\"expr\">a = 5 - 2√6</span> و <span dir=\"ltr\" class=\"expr\">b = 5 + 2√6</span>، و قد رأينا أنّ <span dir=\"ltr\" class=\"expr\">a × b = 1</span> أحسب<span dir=\"ltr\" class=\"expr\">: b<sup>7</sup> (a<sup>2</sup> b)<sup>3</sup>/(a<sup>-3</sup> b) = (5 + 2√6)<sup>7</sup> × ((5 - 2√6)<sup>2</sup> × (5 + 2√6))<sup>3</sup>/((5 - 2√6)<sup>-3</sup> × (5 + 2√6))</span>",
    correction: [{"quoi":"نجمع أسّ 5 + 2√6","math":"<span dir=\"ltr\" class=\"expr\">7 + 3 + (-1) = 9</span>"},{"quoi":"نجمع أسّ 5 - 2√6","math":"<span dir=\"ltr\" class=\"expr\">6 + 3 = 9</span>"},{"quoi":"العددان مترافقان","math":"<span dir=\"ltr\" class=\"expr\">(a - b)(a + b) = a<sup>2</sup> - b<sup>2</sup></span>"},{"quoi":"نحسب جداء الأساسين","math":"<span dir=\"ltr\" class=\"expr\">(5 + 2√6) × (5 - 2√6) = 1</span>"},{"quoi":"نفصل ما يتقابل","math":"<span dir=\"ltr\" class=\"expr\">(5 + 2√6)<sup>9</sup> × (5 - 2√6)<sup>9</sup> = ((5 + 2√6) × (5 - 2√6))<sup>9</sup></span>"},{"quoi":"نعوّض بالجداء","math":"<span dir=\"ltr\" class=\"expr\">((5 + 2√6) × (5 - 2√6))<sup>9</sup> = 1<sup>9</sup></span>"},{"quoi":"قوّة العدد 1","math":"<span dir=\"ltr\" class=\"expr\">1<sup>9</sup> = 1</span>"},{"quoi":"النتيجة","math":"<span dir=\"ltr\" class=\"expr\">A = 1</span>"}],
