    enonce: "نعتبر <span dir=\"ltr\" class=\"expr\">X = a<sup>-3</sup> b<sup>-3</sup></span> حيث <span dir=\"ltr\" class=\"expr\">a = √3 + 1</span> و <span dir=\"ltr\" class=\"expr\">b = √3 - 1</span> أحسب<span dir=\"ltr\" class=\"expr\">: X = (√3 + 1)<sup>-3</sup> × (√3 - 1)<sup>-3</sup></span>",
    correction: [{"quoi":"العددان مترافقان","math":"<span dir=\"ltr\" class=\"expr\">(a - b)(a + b) = a<sup>2</sup> - b<sup>2</sup></span>"},{"quoi":"نحسب جداء الأساسين","math":"<span dir=\"ltr\" class=\"expr\">(√3 + 1) × (√3 - 1) = 2</span>"},{"quoi":"نفصل ما يتقابل","math":"<span dir=\"ltr\" class=\"expr\">(√3 + 1)<sup>-3</sup> × (√3 - 1)<sup>-3</sup> = ((√3 + 1) × (√3 - 1))<sup>-3</sup></span>"},{"quoi":"نعوّض بالجداء","math":"<span dir=\"ltr\" class=\"expr\">((√3 + 1) × (√3 - 1))<sup>-3</sup> = 2<sup>-3</sup></span>"},{"quoi":"ما بقي","math":"<span dir=\"ltr\" class=\"expr\">A = 2<sup>-3</sup></span>"},{"quoi":"النتيجة","math":"<span dir=\"ltr\" class=\"expr\">A = <span class=\"frac\"><span class=\"num\">1</span><span class=\"den\">8</span></span></span>"}],
    indice: "لا تنشر: احسب جداء الأساسين أوّلا",
