    correction: [{"quoi":"العددان مترافقان","math":"<span dir=\"ltr\" class=\"expr\">(a - b)(a + b) = a<sup>2</sup> - b<sup>2</sup></span>"},{"quoi":"نحسب جداء الأساسين","math":"<span dir=\"ltr\" class=\"expr\">(1 + √3) × (1 - √3) = -2</span>"},{"quoi":"نفصل ما يتقابل","math":"<span dir=\"ltr\" class=\"expr\">(1 + √3)<sup>-2</sup> × (1 - √3)<sup>-2</sup> = ((1 + √3) × (1 - √3))<sup>-2</sup></span>"},{"quoi":"نعوّض بالجداء","math":"<span dir=\"ltr\" class=\"expr\">((1 + √3) × (1 - √3))<sup>-2</sup> = (-2)<sup>-2</sup></span>"},{"quoi":"ما بقي","math":"<span dir=\"ltr\" class=\"expr\">A = (-2)<sup>-2</sup></span>"},{"quoi":"النتيجة","math":"<span dir=\"ltr\" class=\"expr\">A = <span class=\"frac\"><span class=\"num\">1</span><span class=\"den\">4</span></span></span>"}],
