    correction: [{"quoi":"نحدّد الأولوية","math":"كلّ حدّ على حدة، ثمّ نجمع — و القوى قبل الضرب"},{"quoi":"نحسب الحدّ « 4√7 »","math":"<span dir=\"ltr\" class=\"expr\">4√7 = 4 √7</span>"},{"quoi":"نحسب الحدّ « 3√7 »","math":"<span dir=\"ltr\" class=\"expr\">3√7 = 3 √7</span>"},{"quoi":"نعيد كتابة العبارة","math":"<span dir=\"ltr\" class=\"expr\">A = 4 √7 + 3 √7</span>"},{"quoi":"النتيجة","math":"<span dir=\"ltr\" class=\"expr\">A = 7 √7</span>"}],
    indice: "احسب كلّ حدّ وحده، ثمّ اجمع",
