    enonce: "أحسب: <span dir=\"ltr\" class=\"expr\">A = (2(√3)<sup>-1</sup> - √<span class=\"frac\"><span class=\"num\">3</span><span class=\"den\">2</span></span>)<sup>2</sup></span>",
    correction: [{"quoi":"نحدّد الأولوية","math":"ما داخل القوس أوّلا، ثمّ القوّة"},{"quoi":"نبسّط ما داخل القوس","math":"<span dir=\"ltr\" class=\"expr\">2(√3)<sup>-1</sup> - √<span class=\"frac\"><span class=\"num\">3</span><span class=\"den\">2</span></span> = <span class=\"frac\"><span class=\"num\">1</span><span class=\"den\">6</span></span> √3</span>"},{"quoi":"نرفع إلى القوّة","math":"<span dir=\"ltr\" class=\"expr\">(<span class=\"frac\"><span class=\"num\">1</span><span class=\"den\">6</span></span> √3)<sup>2</sup> = <span class=\"frac\"><span class=\"num\">1</span><span class=\"den\">12</span></span></span>"},{"quoi":"النتيجة","math":"<span dir=\"ltr\" class=\"expr\">A = <span class=\"frac\"><span class=\"num\">1</span><span class=\"den\">12</span></span></span>"}],
    indice: "ابدأ بما داخل القوس",
